import { describe, expect, it } from 'vitest'
import {
  findActiveSettingsNavItem,
  getVisibleSettingsNavGroups,
  isSettingsItemActive,
  resolveSettingsLandingHref,
} from '@/lib/settings/navigation'

describe('settings navigation', () => {
  it('falls back to personal settings when no workspace permissions are granted', () => {
    const permissions = new Set<string>()
    const groups = getVisibleSettingsNavGroups(permissions)

    expect(resolveSettingsLandingHref(permissions)).toBe('/settings/account/profile')
    expect(groups.map((group) => group.label)).toEqual(['Personal'])
    expect(groups[0]?.items.map((item) => item.label)).toEqual(['My profile', 'Data & security'])
  })

  it('keeps booking and access settings grouped by user mental model', () => {
    const permissions = new Set<string>(['settings.booking_page', 'settings.integrations'])
    const groups = getVisibleSettingsNavGroups(permissions)

    expect(resolveSettingsLandingHref(permissions)).toBe('/settings/studio/booking-page')
    expect(groups.map((group) => group.label)).toEqual([
      'Booking Experience',
      'Team & Access',
      'Personal',
    ])
    expect(groups[0]?.items.map((item) => item.label)).toEqual(['Booking page'])
    expect(groups[1]?.items.map((item) => item.label)).toEqual(['Connected apps'])
  })

  it('recognizes the dedicated roles and permissions route as active', () => {
    const permissions = new Set<string>(['settings.team', 'settings.integrations'])
    const groups = getVisibleSettingsNavGroups(permissions)
    const match = findActiveSettingsNavItem('/settings/team/permissions', groups)

    expect(isSettingsItemActive('/settings/team/permissions', '/settings/team/permissions')).toBe(true)
    expect(match?.group.label).toBe('Team & Access')
    expect(match?.item.label).toBe('Roles & permissions')

