import { describe, expect, it } from 'vitest'
import {
  locationStepSchema,
  serviceStepSchema,
  studioStepSchema,
} from '@/lib/onboarding/schemas'

// ─── studioStepSchema ─────────────────────────────────────────────────────────

describe('studioStepSchema', () => {
  const base = {
    studioName: 'Dark Matter Tattoo',
    timezone: 'America/Los_Angeles',
    fullName: 'Alex Rivera',
  }

  it('accepts a fully valid studio step', () => {
    expect(studioStepSchema.safeParse(base).success).toBe(true)
  })

  it('accepts optional specialties as an array of strings', () => {
    const result = studioStepSchema.safeParse({
      ...base,
      specialties: ['realism', 'blackwork'],
    })
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.specialties).toEqual(['realism', 'blackwork'])
    }
  })

  it('defaults specialties to undefined when omitted', () => {
    const result = studioStepSchema.safeParse(base)
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.specialties).toBeUndefined()
    }
  })

  // studioName boundary — min 2
  it('rejects studioName with length 1', () => {
    const result = studioStepSchema.safeParse({ ...base, studioName: 'X' })
    expect(result.success).toBe(false)
    if (!result.success) {
      expect(result.error.errors[0]?.message).toMatch(/at least 2 characters/)
    }
  })

  it('accepts studioName with length 2', () => {
    expect(studioStepSchema.safeParse({ ...base, studioName: 'AB' }).success).toBe(true)
  })

  it('accepts studioName with length 60', () => {
    expect(
      studioStepSchema.safeParse({ ...base, studioName: 'A'.repeat(60) }).success,
    ).toBe(true)
  })

  it('rejects studioName with length 61', () => {
    const result = studioStepSchema.safeParse({ ...base, studioName: 'A'.repeat(61) })
    expect(result.success).toBe(false)
    if (!result.success) {
      expect(result.error.errors[0]?.message).toMatch(/60 characters/)
    }
  })

  // fullName boundary — min 2, max 80
  it('rejects fullName with length 1', () => {
    expect(studioStepSchema.safeParse({ ...base, fullName: 'X' }).success).toBe(false)
  })

  it('accepts fullName with length 80', () => {
    expect(
      studioStepSchema.safeParse({ ...base, fullName: 'A'.repeat(80) }).success,
    ).toBe(true)
  })

  it('rejects fullName with length 81', () => {
    expect(
      studioStepSchema.safeParse({ ...base, fullName: 'A'.repeat(81) }).success,
    ).toBe(false)
  })

  // timezone required
  it('rejects empty timezone', () => {
    const result = studioStepSchema.safeParse({ ...base, timezone: '' })
    expect(result.success).toBe(false)
  })

  // type mismatches
  it('rejects non-string studioName', () => {
    expect(studioStepSchema.safeParse({ ...base, studioName: 123 }).success).toBe(false)
  })

  it('rejects non-array specialties', () => {
    expect(
      studioStepSchema.safeParse({ ...base, specialties: 'realism' }).success,
    ).toBe(false)
  })
})

// ─── locationStepSchema ───────────────────────────────────────────────────────

describe('locationStepSchema', () => {
  const base = {
    locationName: 'Main Studio',
    city: 'Los Angeles',
    country: 'US',
  }

  it('accepts a valid minimal location step', () => {
    expect(locationStepSchema.safeParse(base).success).toBe(true)
  })

  it('accepts a fully populated location step', () => {
    const result = locationStepSchema.safeParse({
      ...base,
      address: '123 Sunset Blvd',
      state: 'CA',
      zip: '90001',
      phone: '+13105550000',
    })
    expect(result.success).toBe(true)
  })

  it('locationName defaults to "Main Studio" when omitted', () => {
    const result = locationStepSchema.safeParse({ city: 'London', country: 'GB' })
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.locationName).toBe('Main Studio')
    }
  })

  it('rejects locationName shorter than 2 chars', () => {
    expect(locationStepSchema.safeParse({ ...base, locationName: 'X' }).success).toBe(false)
  })

  it('rejects city shorter than 2 chars', () => {
    expect(locationStepSchema.safeParse({ ...base, city: 'X' }).success).toBe(false)
  })

  it('rejects country shorter than 2 chars', () => {
    expect(locationStepSchema.safeParse({ ...base, country: 'X' }).success).toBe(false)
  })

  it('treats all optional fields as absent when not provided', () => {
    const result = locationStepSchema.safeParse(base)
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.phone).toBeUndefined()
      expect(result.data.address).toBeUndefined()
      expect(result.data.state).toBeUndefined()
      expect(result.data.zip).toBeUndefined()
    }
  })

  it('rejects non-string city', () => {
    expect(locationStepSchema.safeParse({ ...base, city: 42 }).success).toBe(false)
  })
})

// ─── serviceStepSchema ────────────────────────────────────────────────────────

describe('serviceStepSchema', () => {
  const base = {
    serviceName: 'Standard session',
    durationMin: 120,
    basePrice: 300,
    depositPct: 25,
  }

  it('accepts a valid service step', () => {
    expect(serviceStepSchema.safeParse(base).success).toBe(true)
  })

  it('accepts basePrice of 0 (free service)', () => {
    expect(serviceStepSchema.safeParse({ ...base, basePrice: 0 }).success).toBe(true)
  })

  it('rejects negative basePrice', () => {
    const result = serviceStepSchema.safeParse({ ...base, basePrice: -1 })
    expect(result.success).toBe(false)
    if (!result.success) {
      expect(result.error.errors[0]?.message).toMatch(/0 or more/)
    }
  })

  it('accepts decimal basePrice', () => {
    expect(serviceStepSchema.safeParse({ ...base, basePrice: 199.99 }).success).toBe(true)
  })

  it('accepts integer basePrice', () => {
    expect(serviceStepSchema.safeParse({ ...base, basePrice: 300 }).success).toBe(true)
  })

  // durationMin boundaries
  it('rejects durationMin below 15 (value 10)', () => {
    const result = serviceStepSchema.safeParse({ ...base, durationMin: 10 })
    expect(result.success).toBe(false)
    if (!result.success) {
      expect(result.error.errors[0]?.message).toMatch(/at least 15/)
    }
  })

  it('accepts durationMin of 15 (minimum)', () => {
    expect(serviceStepSchema.safeParse({ ...base, durationMin: 15 }).success).toBe(true)
  })

  it('accepts durationMin of 480 (maximum)', () => {
    expect(serviceStepSchema.safeParse({ ...base, durationMin: 480 }).success).toBe(true)
  })

  it('rejects durationMin above 480 (value 500)', () => {
    const result = serviceStepSchema.safeParse({ ...base, durationMin: 500 })
    expect(result.success).toBe(false)
    if (!result.success) {
      expect(result.error.errors[0]?.message).toMatch(/480/)
    }
  })

  it('rejects non-integer durationMin', () => {
    const result = serviceStepSchema.safeParse({ ...base, durationMin: 30.5 })
    expect(result.success).toBe(false)
    if (!result.success) {
      expect(result.error.errors[0]?.message).toMatch(/whole number/)
    }
  })

  // depositPct boundaries
  it('accepts depositPct of 0', () => {
    expect(serviceStepSchema.safeParse({ ...base, depositPct: 0 }).success).toBe(true)
  })

  it('accepts depositPct of 100', () => {
    expect(serviceStepSchema.safeParse({ ...base, depositPct: 100 }).success).toBe(true)
  })

  it('rejects depositPct above 100', () => {
    const result = serviceStepSchema.safeParse({ ...base, depositPct: 101 })
    expect(result.success).toBe(false)
    if (!result.success) {
      expect(result.error.errors[0]?.message).toMatch(/100%/)
    }
  })

  it('rejects depositPct below 0', () => {
    const result = serviceStepSchema.safeParse({ ...base, depositPct: -1 })
    expect(result.success).toBe(false)
  })

  it('treats omitted depositPct as optional (undefined)', () => {
    const result = serviceStepSchema.safeParse({
      serviceName: 'Walk-in',
      durationMin: 30,
      basePrice: 80,
    })
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.depositPct).toBeUndefined()
    }
  })

  it('accepts optional description up to 500 chars', () => {
    expect(
      serviceStepSchema.safeParse({ ...base, description: 'x'.repeat(500) }).success,
    ).toBe(true)
  })

  it('rejects description over 500 chars', () => {
    expect(
      serviceStepSchema.safeParse({ ...base, description: 'x'.repeat(501) }).success,
    ).toBe(false)
  })

  it('rejects non-string serviceName', () => {
    expect(serviceStepSchema.safeParse({ ...base, serviceName: true }).success).toBe(false)
  })
})

import { describe, expect, it } from 'vitest'
import {
  SERVICE_TEMPLATES,
  getTemplateById,
} from '@/lib/onboarding/service-templates'

// ─── Structure ────────────────────────────────────────────────────────────────

describe('SERVICE_TEMPLATES array', () => {
