    expect(t?.durationMin).toBe(120)
    expect(t?.basePrice).toBe(300)
    expect(t?.depositPct).toBe(25)
  })

  it('returns undefined for an unknown id', () => {
    expect(getTemplateById('nonexistent')).toBeUndefined()
  })

  it('returns undefined for an empty string', () => {
    expect(getTemplateById('')).toBeUndefined()
  })

  it('returns the small-flash template', () => {
    const t = getTemplateById('small-flash')
    expect(t?.durationMin).toBe(30)
    expect(t?.basePrice).toBe(100)
    expect(t?.depositPct).toBe(20)
  })

  it('returns the consultation template (free, no deposit)', () => {
    const t = getTemplateById('consultation')
    expect(t?.basePrice).toBe(0)
    expect(t?.depositPct).toBe(0)
  })
})

// ─── pct → cents conversion (mirrors saveServiceStep logic) ──────────────────
//
// The conversion in app/actions/onboarding.ts lines 315-317:
//   const basePriceCents = Math.round(basePrice * 100)
//   const depositCents   = Math.round((depositPct / 100) * basePriceCents)
//   const depositRequired = depositPct > 0

function toCents(basePrice: number, depositPct: number) {
  const basePriceCents = Math.round(basePrice * 100)
  const depositCents = Math.round((depositPct / 100) * basePriceCents)
  const depositRequired = depositPct > 0
  return { basePriceCents, depositCents, depositRequired }
}

describe('pct-to-cents conversion (saveServiceStep logic)', () => {
  it('standard session: $300, 25% → base=30000, deposit=7500, required=true', () => {
    expect(toCents(300, 25)).toEqual({
      basePriceCents: 30000,
      depositCents: 7500,
      depositRequired: true,
    })
  })

  it('free consultation: $0, 0% → base=0, deposit=0, required=false', () => {
    expect(toCents(0, 0)).toEqual({
      basePriceCents: 0,
      depositCents: 0,
      depositRequired: false,
    })
  })

  it('small flash: $100, 20% → base=10000, deposit=2000, required=true', () => {
    expect(toCents(100, 20)).toEqual({
      basePriceCents: 10000,
      depositCents: 2000,
      depositRequired: true,
    })
  })

  it('full-day: $1200, 30% → base=120000, deposit=36000, required=true', () => {
    expect(toCents(1200, 30)).toEqual({
      basePriceCents: 120000,
      depositCents: 36000,
      depositRequired: true,
    })
  })

  it('non-zero price with 0% deposit → required=false, deposit=0', () => {
    expect(toCents(150, 0)).toEqual({
      basePriceCents: 15000,
      depositCents: 0,
      depositRequired: false,
    })
  })

  it('decimal price rounds correctly: $199.99, 10% → base=19999, deposit=2000', () => {
    const result = toCents(199.99, 10)
    expect(result.basePriceCents).toBe(19999)
    // Math.round((10/100) * 19999) = Math.round(1999.9) = 2000
    expect(result.depositCents).toBe(2000)
    expect(result.depositRequired).toBe(true)
  })

  it('SERVICE_TEMPLATES standard template produces expected cents', () => {
    const t = getTemplateById('standard')
    expect(t).toBeDefined()
    if (!t) return
    expect(toCents(t.basePrice, t.depositPct)).toEqual({
      basePriceCents: 30000,
      depositCents: 7500,
      depositRequired: true,
    })
  })
})

/**
 * E2E — Onboarding wizard (4-step flow)
 *
 * Scenarios:
 *   a. Happy-path end-to-end: signup → 4 steps → /dashboard
 *   b. Resume after refresh: complete steps 1+2, refresh at step 3, verify resume
 *   c. Skip-for-now: skip steps 2 and 3, verify minimum DB rows + step 4 reached
 *
 * All tests create unique accounts (email with timestamp) to avoid collisions.
 * Orphan rows in dev DB are intentional — no cleanup helper exists yet.
 */

import { test, expect, type Page } from '@playwright/test'

// ─── Helpers ──────────────────────────────────────────────────────────────────

function uniqueEmail() {
  return `onboarding+${Date.now()}@inkos-test.dev`
}

/**
 * Signs up a fresh user via the /signup page and lands on /onboarding.
 * Returns the email so callers can re-authenticate if needed.
 */
async function signUpAndLandOnOnboarding(
  page: Page,
  email: string,
  password = 'OnboardTest2026!Aa',
): Promise<void> {
  await page.goto('/signup')
  await page.waitForURL(/signup/, { timeout: 15_000 })

  await page.getByLabel(/email/i).fill(email)
  await page.getByLabel(/password/i).fill(password)
  await page.getByRole('button', { name: /sign up|create account|get started/i }).click()

  // After signup, should land on onboarding (may go through /dashboard first if
  // redirect logic differs, but fresh accounts always get /onboarding)
  await page.waitForURL(/onboarding/, { timeout: 20_000 })
}

/**
 * Programmatic sign-in via the same login API used by smoke fixtures.
 * Used to re-authenticate the same user after a page reload.
 */
async function programmaticSignIn(page: Page, email: string, password: string) {
  const res = await page.request.post('/api/auth/login', {
    data: { email, password },
  })
  if (!res.ok()) {
    throw new Error(`Re-auth failed: ${res.status()} — ${email}`)
  }
}

// ─── Test a — Happy path end-to-end ──────────────────────────────────────────

test('onboarding happy path: signup → 4 steps → /dashboard', async ({ page }) => {
  test.slow() // ~60s budget

  const email = uniqueEmail()
  const password = 'OnboardTest2026!Aa'

  // Step: Signup
  await signUpAndLandOnOnboarding(page, email, password)

  // ── Step 1: Studio ─────────────────────────────────────────────────────────
  await expect(page.getByText(/your studio/i)).toBeVisible({ timeout: 10_000 })

  const studioNameInput = page.getByLabel(/studio name/i)
  await expect(studioNameInput).toBeFocused({ timeout: 5_000 })

  await studioNameInput.fill('Dark Matter Tattoo')

  // SlugPreview should update — look for the slug text anywhere on the page
  await expect(page.getByText(/dark-matter-tattoo/)).toBeVisible({ timeout: 5_000 })

  // TimezoneCombobox should be pre-populated (any non-empty value)
  const timezoneField = page
    .getByRole('combobox', { name: /timezone/i })
    .or(page.locator('[data-testid="timezone-combobox"]'))
  await expect(timezoneField).toBeVisible()
  const tzValue = await timezoneField.inputValue().catch(() => '')
  const tzText = await timezoneField.textContent().catch(() => '')
  // At least one of the two should be truthy
  expect(tzValue || tzText).toBeTruthy()

  await page.getByLabel(/your name|full name/i).fill('Alex Rivera')

  // Specialties chip picker — optional, select 2 chips
  const chips = page.getByRole('button', { name: /realism|blackwork|neo-traditional|traditional|japanese|geometric|watercolor/i })
  const chipCount = await chips.count()
  if (chipCount >= 2) {
    await chips.first().click()
    await chips.nth(1).click()
  }

  await page.getByRole('button', { name: /^continue$/i }).click()

  // ── Step 2: Location ───────────────────────────────────────────────────────
  await expect(page.getByText(/one location/i)).toBeVisible({ timeout: 10_000 })

  await page.getByLabel(/location name/i).fill('Main Studio')
  await page.getByLabel(/city/i).fill('Los Angeles')

  // Country — may be a combobox or a text input
  const countryField = page.getByLabel(/country/i)
  await countryField.fill('United States')
  // If it's a combobox, select the first option
  const countryOption = page.getByRole('option', { name: /united states/i })
  if (await countryOption.isVisible({ timeout: 2_000 }).catch(() => false)) {
    await countryOption.click()
  }

  await page.getByRole('button', { name: /^continue$/i }).click()

  // ── Step 3: First service ──────────────────────────────────────────────────
  await expect(page.getByText(/your first service/i)).toBeVisible({ timeout: 10_000 })

  // Click the "Standard session" template card
  await page.getByText(/standard session/i).first().click()

  // Verify form fields are pre-filled by the template
  const durationField = page.getByLabel(/duration/i)
  await expect(durationField).toHaveValue('120')
  const priceField = page.getByLabel(/price/i)
  const priceValue = await priceField.inputValue()
  expect(Number(priceValue)).toBe(300)

  await page.getByRole('button', { name: /^continue$/i }).click()

  // ── Step 4: Go live ────────────────────────────────────────────────────────
  await expect(page.getByText(/^live\.?$/i)).toBeVisible({ timeout: 15_000 })

  // Booking URL in JetBrains Mono — contains the slug
  const bookingUrlEl = page.locator('span, code, p').filter({ hasText: /book\.inkos\.app\// })
  await expect(bookingUrlEl.first()).toBeVisible()
  const bookingUrl = await bookingUrlEl.first().textContent()
  expect(bookingUrl).toMatch(/book\.inkos\.app\/dark-matter-tattoo/)

  // QR code rendered as <svg> or <canvas>
